-- The two checklists published on 2026-11-05: The Week Before a Court Date
-- (Court) and Using Music to Shift a Bad Hour (Music).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-05`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('the-week-before-a-court-date', 'The Week Before a Court Date', 'For the week before a court date, when the waiting is worse than the day itself. It gets your questions written down for the lawyer, the papers in one folder, somebody arranged to come with you, and the day after kept clear.', 'Court', '["Write down the three questions you most want answered — a lawyer''s half hour goes fast otherwise.", "Put every document in one folder in date order — hunting for a page on the morning is its own ordeal.", "Visit the building beforehand if you can — a corridor you have already walked is not a strange place.", "Ask what time you actually need to be there — most of a court day is waiting, and waiting plans better.", "Arrange who is coming with you — nobody should hear a decision alone in a hallway.", "Decide what you will not say on the day — a sentence prepared is better than one that escapes.", "Book the day after off as well — an outcome needs somewhere to land that is not your desk.", "Eat something before you go even if you cannot face it — an empty day makes everything feel worse.", "Write down what you will do either way — both outcomes need a next step, not only the bad one."]'::jsonb, 'as needed', array['Stress', 'Worry', 'Resilience']::text[], 1, '2026-11-05T16:00:00+00:00'::timestamptz),
  ('using-music-to-shift-a-bad-hour', 'Using Music to Shift a Bad Hour', 'For an hour that has gone wrong and needs shifting rather than analyzing. It picks the mood to aim at, starts from where you actually are, keeps one playlist you never have to think about, and puts a track before the hard task.', 'Music', '["Name the mood you want to get to, not the one you are in — music works better when it is aimed.", "Start with where you actually are — a sad song first lets a brighter one land later.", "Keep one playlist you never have to think about — a list you trust saves deciding on a bad day.", "Put something on before the hard task, not during — a start you can hear beats a silent one.", "Use headphones when the room is too much — one layer between you and everything else helps.", "Play something from a good year once a week — a song can hand back a whole season of your life.", "Try the same album at the same time each evening — a repeated sound becomes a signal to wind down.", "Notice what you skip and take it off the list — a song you always skip is working against you.", "Sing or move to one track with nobody watching — music in the body does what listening alone does not."]'::jsonb, 'as needed', array['Emotion Regulation', 'Mindfulness', 'Self-Care']::text[], 1, '2026-11-05T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
